import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Page Finder Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Page Finder"},"headers":[{"level":2,"title":"Linking to Pages","slug":"linking-to-pages","link":"#linking-to-pages","children":[]},{"level":2,"title":"Filtering Page Types","slug":"filtering-page-types","link":"#filtering-page-types","children":[]},{"level":2,"title":"Creating New Page Types","slug":"creating-new-page-types","link":"#creating-new-page-types","children":[{"level":3,"title":"Registering Page Types","slug":"registering-page-types","link":"#registering-page-types","children":[]},{"level":3,"title":"Providing Type Information","slug":"providing-type-information","link":"#providing-type-information","children":[{"level":4,"title":"Finding CMS Pages","slug":"finding-cms-pages","link":"#finding-cms-pages","children":[]},{"level":4,"title":"Nested References","slug":"nested-references","link":"#nested-references","children":[]}]},{"level":3,"title":"Resolving Page Links","slug":"resolving-page-links","link":"#resolving-page-links","children":[{"level":4,"title":"Nested Items","slug":"nested-items","link":"#nested-items","children":[]},{"level":4,"title":"Multi-site Links","slug":"multi-site-links","link":"#multi-site-links","children":[]}]}]}],"relativePath":"4.x/element/form/widget-pagefinder.md","filePath":"4.x/element/form/widget-pagefinder.md"}'),r={name:"4.x/element/form/widget-pagefinder.md"};function u(k,s,g,d,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"Page Finder Field",-1)),a(e),s[1]||(s[1]=i(`<p><code>pagefinder</code> - renders a field for selecting a page link. Expanding the field displays the picker to locate a page. The resulting selection is a string that contains the type and reference.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">featured_page</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Featured Page
    <span class="token key atrule">type</span><span class="token punctuation">:</span> pagefinder
</code></pre></div><p>The selected value is stored using the following format.</p><div class="language- extra-class"><pre class="language-text"><code>october://&lt;TYPE&gt;@link/&lt;REFERENCE&gt;?&lt;PARAM&gt;=&lt;VALUE&gt;
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>singleMode</strong></td><td>only allows items to be selected that resolve to a single URL. Default: <code>false</code></td></tr><tr><td><strong>allowCustomUrl</strong></td><td>controls whether the free-form URL option appears in the type dropdown. Default: <code>true</code></td></tr><tr><td><strong>allowedTypes</strong></td><td>an array of type codes to show in the type dropdown, acting as a whitelist. Default: <code>null</code></td></tr><tr><td><strong>excludedTypes</strong></td><td>an array of type codes to hide from the type dropdown, acting as a blacklist. Default: <code>null</code></td></tr></tbody></table></div><div class="custom-block tip"><p>Resolve the <code>pagefinder</code> value in lists using the <a href="./../lists/column-linkage.html">linkage column type</a>.</p></div><h2 id="linking-to-pages"><a href="#linking-to-pages" class="header-anchor">#</a> Linking to Pages</h2><p>Use the <a href="./../../markup/filter/link.html"><code>|link</code> Twig filter</a> to convert the page finder value to a URL.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> featured_page<span class="token operator">|</span>link <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Use the <a href="./../../markup/tag/content.html"><code>|content</code> Twig filter</a> to process HTML markup and replace all links within the content.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blog_html<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="filtering-page-types"><a href="#filtering-page-types" class="header-anchor">#</a> Filtering Page Types</h2><p>By default the page finder shows all registered page types, including the URL type and any types registered by plugins and Tailor blueprints. Page types that have no available CMS pages are automatically hidden.</p><p>Use the <code>allowedTypes</code> property to restrict the type dropdown to specific types only. For example, to only allow CMS page selection.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">custom_page</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Custom Page
    <span class="token key atrule">type</span><span class="token punctuation">:</span> pagefinder
    <span class="token key atrule">allowedTypes</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> cms<span class="token punctuation">-</span>page
</code></pre></div><p>Use <code>excludedTypes</code> to hide specific types from the dropdown.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">custom_page</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Custom Page
    <span class="token key atrule">type</span><span class="token punctuation">:</span> pagefinder
    <span class="token key atrule">excludedTypes</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> url
</code></pre></div><p>Set <code>allowCustomUrl</code> to <code>false</code> to remove the free-form URL option independently of the type filters.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">custom_page</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Custom Page
    <span class="token key atrule">type</span><span class="token punctuation">:</span> pagefinder
    <span class="token key atrule">allowCustomUrl</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="creating-new-page-types"><a href="#creating-new-page-types" class="header-anchor">#</a> Creating New Page Types</h2><p>Plugins can extend the page finder with new page types by listening to three events. The following is a complete example that registers a <strong>blog-post</strong> page type, provides a list of selectable references and compatible CMS pages, and resolves the link URL at runtime.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Register the page type</span>
    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;blog-post&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Post&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Provide references and CMS pages for the type</span>
    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.getTypeInfo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">BlogPost</span><span class="token operator">::</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPost&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Resolve item to a URL</span>
    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">BlogPost</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">reference</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token variable">$pageUrl</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span> <span class="token operator">==</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;mtime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">updated_at</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>It&#39;s recommended to use the plugin name in the type codes (e.g. <code>blog-post</code> instead of <code>post</code>) to avoid conflicts with other providers.</p></div><p>The following sections explain each event in detail.</p><h3 id="registering-page-types"><a href="#registering-page-types" class="header-anchor">#</a> Registering Page Types</h3><p>The <code>cms.pageLookup.listTypes</code> event returns an associative array of type codes and their labels.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog-post&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Post&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For types that support nested subitems (e.g. linking to all blog posts at once), set <code>nesting</code> to <code>true</code>. These types are excluded when the page finder is set to <code>singleMode</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog-post&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Post&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;blog-posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;All Blog Posts&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;nesting&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>A legacy format <code>[&#39;All Blog Posts&#39;, true]</code> (numeric keys with a boolean last element) is also supported for backward compatibility.</p></div><h3 id="providing-type-information"><a href="#providing-type-information" class="header-anchor">#</a> Providing Type Information</h3><p>The <code>cms.pageLookup.getTypeInfo</code> event returns the selectable references and compatible CMS pages for a given type. The handler should check the <code>$type</code> argument and only return data for types it owns.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.getTypeInfo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">BlogPost</span><span class="token operator">::</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPost&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>references</code> element is a list of selectable records, keyed by ID. The <code>cmsPages</code> element should be an array of <code>Cms\\Classes\\Page</code> objects that can display this type.</p><h4 id="finding-cms-pages"><a href="#finding-cms-pages" class="header-anchor">#</a> Finding CMS Pages</h4><p>Use <code>withComponent</code> to find all pages that use a specific component.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPost&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><p>Use <code>whereComponent</code> to match a component with a specific property value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">whereComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;section&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;handle&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Your\\Handle&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="nested-references"><a href="#nested-references" class="header-anchor">#</a> Nested References</h4><p>For models with a tree structure, references can include subitems.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;item-key&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Item title&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;child-key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child title&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span>
</code></pre></div><h3 id="resolving-page-links"><a href="#resolving-page-links" class="header-anchor">#</a> Resolving Page Links</h3><p>The <code>cms.pageLookup.resolveItem</code> event resolves the stored reference to an actual URL. It fires each time a link is rendered on the frontend. The handler takes four arguments:</p><ul><li><code>$type</code> - the item type name. Only handle types your plugin provides, return nothing for others.</li><li><code>$item</code> - the item object (<code>Cms\\Models\\PageLookupItem</code>) with properties: <code>type</code>, <code>reference</code>, <code>cmsPage</code>.</li><li><code>$url</code> - the current page URL (lowercase). Compare with generated URLs to set <code>isActive</code>.</li><li><code>$theme</code> - the current theme object (<code>Cms\\Classes\\Theme</code>).</li></ul><p>The handler should return an array with the following keys.</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>The resolved public URL (required).</td></tr><tr><td><strong>isActive</strong></td><td>Whether the link matches the current page (required).</td></tr><tr><td><strong>title</strong></td><td>Display title override, optional.</td></tr><tr><td><strong>mtime</strong></td><td>Last modification time, optional.</td></tr><tr><td><strong>items</strong></td><td>Child items array, only when <code>$item-&gt;nesting</code> is true.</td></tr><tr><td><strong>sites</strong></td><td>Multi-site URL alternatives, only when <code>$item-&gt;sites</code> is true.</td></tr></tbody></table></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">BlogPost</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">reference</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$pageUrl</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span> <span class="token operator">==</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;mtime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">updated_at</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>The resolving process runs on every frontend page render, so cache the information required for resolving items if possible.</p></div><h4 id="nested-items"><a href="#nested-items" class="header-anchor">#</a> Nested Items</h4><p>For types registered with <code>nesting</code> support, the resolver should return child items when <code>$item-&gt;nesting</code> is true. Each child item uses the same keys (<code>url</code>, <code>isActive</code>, <code>title</code>, <code>mtime</code>) and may contain its own <code>items</code> for hierarchical structures.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;all-blog-posts&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$controller</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Controller</span><span class="token punctuation">(</span><span class="token variable">$theme</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$items</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name static-context">BlogPost</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$pageUrl</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$items</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span> <span class="token operator">==</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;mtime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">updated_at</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$items</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="multi-site-links"><a href="#multi-site-links" class="header-anchor">#</a> Multi-site Links</h4><p>When <code>$item-&gt;sites</code> is true, the resolver can return alternative URLs for other sites using the <code>Cms</code> and <code>Site</code> facades.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Inside the resolveItem handler</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">sites</span> <span class="token operator">&amp;&amp;</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasMultiSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$page</span> <span class="token operator">=</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">loadCached</span><span class="token punctuation">(</span><span class="token variable">$theme</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token variable">$site</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$sites</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">siteUrl</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">,</span> <span class="token variable">$site</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;code&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">code</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;locale&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">hard_locale</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sites&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$sites</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

</code></pre></div>`,56))])}const v=p(r,[["render",u]]);export{f as __pageData,v as default};
